INSERT INTO completion_preflight SELECT CASE WHEN NOT (NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1')) OR ((SELECT count(*) FROM spots WHERE (id=201 AND (title<>'中国丝绸博物馆' OR city_id<>1)) OR (id=202 AND (title<>'浙江省博物馆（孤山馆区）' OR city_id<>1)) OR (id=203 AND (title<>'岳王庙' OR city_id<>1)) OR (id=204 AND (title<>'西溪国家湿地公园' OR city_id<>1)) OR (id=205 AND (title<>'成都博物馆' OR city_id<>2)) OR (id=206 AND (title<>'杜甫草堂' OR city_id<>2)) OR (id=207 AND (title<>'成都武侯祠' OR city_id<>2)) OR (id=208 AND (title<>'南阳府衙' OR city_id<>3)) OR (id=209 AND (title<>'内乡县衙' OR city_id<>3)) OR (id=210 AND (title<>'张衡博物馆' OR city_id<>3)) OR (id=211 AND (title<>'清净寺' OR city_id<>4)) OR (id=212 AND (title<>'泉州天后宫' OR city_id<>4)) OR (id=213 AND (title<>'泉州海外交通史博物馆' OR city_id<>4)) OR (id=214 AND (title<>'西街' OR city_id<>4)) OR (id=215 AND (title<>'喜洲古镇' OR city_id<>5)) OR (id=216 AND (title<>'大理州博物馆' OR city_id<>5)) OR (id=217 AND (title<>'蝴蝶泉' OR city_id<>5)))=0 AND (SELECT count(*) FROM social_posts WHERE id BETWEEN 301 AND 312)=0 AND (SELECT count(*) FROM shared_routes WHERE id BETWEEN 301 AND 309)=0) THEN 1 ELSE 0 END;
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 201,1,'中国丝绸博物馆','从一根丝、一件衣服，读懂杭州的另一种文化线索。','中国丝绸博物馆位于西湖附近、玉皇山下，以丝绸、纺织与服饰文化为主题，涉及历史、工艺、保护和当代时尚。它提供了一种不同于湖岸步行的参观方式：从纹样、材料和衣服的结构入手，认识日常物品背后的知识。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 202,1,'浙江省博物馆（孤山馆区）','把一段湖岸散步，接到一段安静的展览阅读。','孤山馆区是浙江省博物馆的参观场所之一，位于西湖孤山片区。这里适合与附近湖岸分段组合，先看一段室外空间，再根据当天实际展览选择参观内容。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 203,1,'岳王庙','在湖畔的纪念空间里，读建筑、碑刻与人物故事。','岳王庙是杭州西湖畔与岳飞纪念相关的重要场所，墓与庙共同形成了人物纪念空间。参观可以先看院落和建筑，再阅读碑刻、匾额与现场说明，把所见内容与人物背景联系起来。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 204,1,'西溪国家湿地公园','沿水道、树影与开放步道，留一个不赶路的半天。','西溪国家湿地公园位于杭州城市西部，以湿地、水道和相关人文空间形成不同于西湖的游览环境。水边植被与步道适合慢看，但整个湿地不能被当作一个很小的步行点位。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 205,2,'成都博物馆','从城市历史与展品细节，打开成都的另一面。','成都博物馆位于天府广场西侧，是认识成都历史文化的综合性博物馆。与街巷中的建筑观察相比，展厅里的器物、图像和说明能提供另一层时间线索，适合给城市游览增加一段集中阅读。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 206,2,'杜甫草堂','在园林、纪念建筑和诗歌线索之间慢慢看。','成都杜甫草堂博物馆以杜甫流寓成都的故居纪念为基础，历代修葺形成了园林与纪念建筑相结合的文化空间。参观既可以从人物和诗歌切入，也可以先观察院落、水面与树木怎样组织视线。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 207,2,'成都武侯祠','把三国人物的阅读，放进真实的纪念建筑与展陈里。','成都武侯祠是与刘备、诸葛亮及蜀汉人物纪念相关的重要场所。可以沿导览认识建筑与纪念空间，再选一段人物介绍、匾额或展陈阅读，让参观从熟悉的故事进入更具体的现场。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 208,3,'南阳府衙','从门、堂与院落的次序，认识古代官署空间。','南阳府衙是了解地方官署建筑与历史的一处实物线索。参观可以先看入口、堂与院落的先后关系，再结合说明理解不同空间的用途；把一座建筑群看成有组织的使用场所，比只记几块匾额更有收获。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 209,3,'内乡县衙','为一座县衙留一段完整时间，比较建筑与制度的关系。','内乡县衙位于南阳所辖内乡县，是保存古代县级官署形制的重要场所。建筑群中的门、堂、后部生活空间等，可以帮助理解一座官署怎样组织工作与生活；参观时先看整体，再选择感兴趣的部分细读。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 210,3,'张衡博物馆','从人物纪念与科学史线索，认识南阳的另一段人文。','张衡博物馆位于南阳卧龙区石桥镇一带，与张衡墓等纪念空间共同提供认识人物文化的线索。参观可以先看人物生平和相关说明，再观察纪念建筑、墓园与展陈如何组织叙述。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 211,4,'清净寺','从石门与建筑细节，认识泉州的多元文化。','清净寺位于泉州涂门街，是认识泉州海外交流与宗教建筑的重要线索。门楼的尖拱、石材与空间层次提供了不同于周边传统建筑的观看方式，适合先看整体，再慢慢阅读说明。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 212,4,'泉州天后宫','沿纪念建筑与石刻，看海洋生活留下的文化线索。','泉州天后宫与妈祖信仰和泉州海外交通历史密切相关。参观可以沿建筑轴线看不同院落、殿宇与石刻，再通过说明了解航海生活和人物信仰如何进入城市空间。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 213,4,'泉州海外交通史博物馆','从器物、船模与石刻，读懂一座港口城市。','泉州海外交通史博物馆以海外交通和海洋文化为重要主题，为理解泉州的对外交流提供器物、图像与历史说明。可以从一件器物的用途切入，再把它放回城市、港口和跨海往来的背景中理解。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 214,4,'西街','在古城的街巷里，把建筑、店铺与日常慢慢串起来。','西街是泉州古城的重要历史街区，与开元寺、传统民居和沿街生活共同构成了认识城市的入口。既能观察街道尺度和建筑细节，也能看到今天的商业与日常怎样使用这些空间。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 215,5,'喜洲古镇','从照壁、院落与街巷，看白族民居的地方表达。','喜洲位于大理市北部，保留了有代表性的白族民居建筑和古镇空间。参观可以从街巷和院落的关系入手，认识照壁、门头和不同建筑细节怎样进入日常生活，不只寻找一张固定构图的照片。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 216,5,'大理州博物馆','用一段展览阅读，补上山水之外的地方历史。','大理州博物馆位于下关片区，通过历史、民族文化及相关专题展陈，提供认识大理的另一种入口。山水旅行之后，可以把器物、建筑模型和说明中的线索同已经看过的古城、古塔联系起来。
INSERT INTO spots(id,city_id,title,intro,description,highlights,transportation,tips,image,source_url,theme,duration_minutes,gallery) SELECT 217,5,'蝴蝶泉','在泉水与树荫之间，给自然观察留一小段时间。','蝴蝶泉位于大理周城一带，与泉水、树木及当地文化共同形成参观内容。可以先看泉边空间和自然环境，再结合现场说明认识相关文化叙述，不把景点名称直接理解成随时都会出现大量蝴蝶。
INSERT INTO completion_authors SELECT CASE WHEN NOT (NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1')) OR (SELECT count(*) FROM users WHERE role='USER' AND username IN ('一碗热面','同行小记','听雨走街','周末出发','地图先行','小林同学','带爸妈散步','慢半拍','木窗与青瓦','清汤少辣','留半天发呆','看展不赶路','轻装慢走','镜头朝外'))=14 THEN 1 ELSE 0 END;
INSERT INTO social_posts(id,user_id,city_id,category,title,body,image,created_at) SELECT 301,(SELECT id FROM users WHERE username='周末出发' AND role='USER'),1,'提问','杭州两天，湖边和博物馆怎么选？','第一次去杭州，周五晚上到，周日下午返程。最想留一个下午给西湖，另一个半天想进博物馆坐下来慢慢看。
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 301,(SELECT id FROM users WHERE username='慢半拍' AND role='USER'),'我会先选一个馆，把另一个留作下雨时的候选。还要取行李的话，周日下午别排太远。','2026-10-25T01:26:41.071Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 301,(SELECT id FROM users WHERE username='一碗热面' AND role='USER'),'先把午饭位置选在结束的那一边，少一次折返就轻松很多。','2026-10-25T01:56:41.071Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_posts(id,user_id,city_id,category,title,body,image,created_at) SELECT 302,(SELECT id FROM users WHERE username='镜头朝外' AND role='USER'),1,'提问','想拍湖面和树影，不追日落也能逛得开心吧','翻相册发现自己总在拍差不多的远景，这次想只带手机，沿一段湖岸试着拍远、中、近三张。
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 302,(SELECT id FROM users WHERE username='听雨走街' AND role='USER'),'我会先想好怎么回去，照片拍到喜欢的就走，不等某一束光。','2026-10-25T04:03:17.975Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 302,(SELECT id FROM users WHERE username='留半天发呆' AND role='USER'),'给自己留一段不拍照的时间也挺好，找个能停的地方看看水面。','2026-10-25T04:27:17.975Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_posts(id,user_id,city_id,category,title,body,image,created_at) SELECT 303,(SELECT id FROM users WHERE username='清汤少辣' AND role='USER'),2,'提问','成都小吃想尝几样，但不太吃辣怎么点？','我和朋友都准备去成都，但口味差得有点远，一个爱红油，一个连蒜都不太想加。钟水饺、担担面都在清单里，又不想一顿吃太多。
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 303,(SELECT id FROM users WHERE username='一碗热面' AND role='USER'),'各点主食挺好，先问一份到底有多少，别觉得是小吃就一口气点一桌。','2026-10-25T06:59:54.879Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 303,(SELECT id FROM users WHERE username='同行小记' AND role='USER'),'下单时把辣油、蒜能不能分开放说清楚，比只说少辣好沟通。','2026-10-25T07:24:54.879Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_posts(id,user_id,city_id,category,title,body,image,created_at) SELECT 304,(SELECT id FROM users WHERE username='看展不赶路' AND role='USER'),2,'提问','成都博物馆和杜甫草堂，想各留半天','比起连逛几条街，我更想在馆里和园林里多待一会儿。准备把成都博物馆和杜甫草堂分开，另留一段去武侯祠。
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 304,(SELECT id FROM users WHERE username='木窗与青瓦' AND role='USER'),'我会留草堂的园林时间，不只看完几个名字就离开。街区真不用全塞进去。','2026-10-25T09:38:31.783Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 304,(SELECT id FROM users WHERE username='周末出发' AND role='USER'),'先确定预约和入口，再看看两个半天中间有没有完整饭点，计划会稳一点。','2026-10-25T10:02:31.783Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_posts(id,user_id,city_id,category,title,body,image,created_at) SELECT 305,(SELECT id FROM users WHERE username='小林同学' AND role='USER'),3,'提问','南阳两天，想看府衙也想去汉画馆','在做南阳的两天计划，武侯祠、汉画馆和府衙都想看，不想一进展厅就开始看表。
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 305,(SELECT id FROM users WHERE username='地图先行' AND role='USER'),'内乡那段先把去程和回程一起查，市区路线和它分开排会清楚很多。','2026-10-25T12:23:08.687Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 305,(SELECT id FROM users WHERE username='看展不赶路' AND role='USER'),'汉画馆可以只挑一个主题慢看，不一定每件都拍，给午饭也留点空。','2026-10-25T12:47:08.687Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_posts(id,user_id,city_id,category,title,body,image,created_at) SELECT 306,(SELECT id FROM users WHERE username='带爸妈散步' AND role='USER'),3,'提问','带爸妈看南阳人文景点，怎么走得轻松点？','爸妈更喜欢听故事、看建筑，对打卡数量没什么要求。我想一处参观完就找地方坐坐，中午喝碗汤，不急着赶下一个地方。
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 306,(SELECT id FROM users WHERE username='轻装慢走' AND role='USER'),'我会先问他们能连续走多久，第二处留成可选。去石桥镇那边要另外算往返。','2026-10-25T15:09:45.591Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 306,(SELECT id FROM users WHERE username='慢半拍' AND role='USER'),'两处都不一定要用满，有一处看得喜欢就多留一会儿，饭点别往后挤。','2026-10-25T15:37:45.591Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_posts(id,user_id,city_id,category,title,body,image,created_at) SELECT 307,(SELECT id FROM users WHERE username='一碗热面' AND role='USER'),4,'提问','泉州半日只逛古城，午饭先选面线糊还是肉粽','准备先去开元寺，再沿西街走一段，吃完午饭就慢慢往回收尾。清净寺想看天气和时间再决定，洛阳桥留到另一天。
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 307,(SELECT id FROM users WHERE username='清汤少辣' AND role='USER'),'先看基础份和加料怎么计价，别还没吃就把所有配料点齐。','2026-10-25T18:03:22.495Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 307,(SELECT id FROM users WHERE username='留半天发呆' AND role='USER'),'反正是散步，先坐下吃一种，另一种留下一餐也不亏。','2026-10-25T18:27:22.495Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_posts(id,user_id,city_id,category,title,body,image,created_at) SELECT 308,(SELECT id FROM users WHERE username='木窗与青瓦' AND role='USER'),4,'提问','看完古城，再去海交馆会不会更容易看懂？','对开元寺、清净寺和天后宫的建筑都很感兴趣，想先走古城，再留一段进海外交通史博物馆。
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 308,(SELECT id FROM users WHERE username='看展不赶路' AND role='USER'),'可以先带一个问题进馆，比如一件器物和港口生活有什么联系，不用一次看完所有主题。','2026-10-25T20:45:59.399Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 308,(SELECT id FROM users WHERE username='镜头朝外' AND role='USER'),'整体加局部挺适合整理照片的，别为了凑角度跑到不开放的位置就好。','2026-10-25T21:07:59.399Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_posts(id,user_id,city_id,category,title,body,image,created_at) SELECT 309,(SELECT id FROM users WHERE username='轻装慢走' AND role='USER'),5,'提问','大理三天不换住处，古城和喜洲分两天','有三天时间，不想每天收拾箱子，准备住同一处。古城、三塔一天，喜洲和蝴蝶泉另留一天，湖边再选一段。
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 309,(SELECT id FROM users WHERE username='地图先行' AND role='USER'),'州博物馆和古城里的市博物馆不是一处，导航时把全名和片区都确认一下。','2026-10-25T23:25:36.303Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 309,(SELECT id FROM users WHERE username='慢半拍' AND role='USER'),'三天里留半天空白挺有用，天气不好就换顺序，不一定还要再加一圈环湖。','2026-10-25T23:49:36.303Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_posts(id,user_id,city_id,category,title,body,image,created_at) SELECT 310,(SELECT id FROM users WHERE username='留半天发呆' AND role='USER'),5,'提问','洱海只去一个片区，不骑车会不会太单调？','我想象的湖边旅行就是走一段、坐一段，拍到喜欢的照片就收工。同行朋友不太想骑车，所以准备先把往返地点定下来。
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 310,(SELECT id FROM users WHERE username='镜头朝外' AND role='USER'),'我也更想在一个地方看看光和水面怎么变，不一定总在路上才算旅行。','2026-10-26T02:19:13.207Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 310,(SELECT id FROM users WHERE username='带爸妈散步' AND role='USER'),'能坐下来休息的话，对同行的人也友好，先确认开放步道和怎么返回就行。','2026-10-26T02:44:13.207Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
INSERT INTO social_posts(id,user_id,city_id,category,title,body,image,created_at) SELECT 311,(SELECT id FROM users WHERE username='同行小记' AND role='USER'),NULL,'经验','结伴做计划，我想先把这三件事聊清楚','在整理这次结伴旅行的清单，发现最想先商量的不是去哪家店，而是：每天大概几点能出门、能连续走多久、哪一处是真的不想错过。
INSERT INTO social_comments(post_id,user_id,body,created_at) SELECT 311,(SELECT id FROM users WHERE username='周末出发' AND role='USER'),'几点出门真的要先说，不然两个人对上午的理解可能差两个小时😂','2026-10-26T05:04:50.111Z' WHERE NOT EXISTS(SELECT 1 FROM schema_migrations WHERE name='completion-content-20261026-v1');
