INSERT INTO social_posts(id,user_id,city_id,category,title,body,image,created_at) SELECT 312,(SELECT id FROM users WHERE username='听雨走街' AND role='USER'),NULL,'经验','雨天备选先列着，不把每天都排满','给自己做了一份可删减的旅行清单：当天只保留一个重点，天气和体力合适再加一处。室内场馆也会先查开放，不是下雨了才临时跑过去碰运气。
